(()=>{
'use strict';
const S=Site,D=FrameData,{esc,art,link,button}=S;
let importURL='',promote={type:'作品封面',ratio:'9:16',title:'雨停之前',subtitle:'有些重逢，是故事重新开始。',author:'一人故事工作室'},reviewChecks=new Set(S.state.projects.flatMap(p=>p.chapters.flatMap(c=>(c.reviewChecks||[]).map(k=>p.id+c.id+k))));
const pid=()=>S.context.parts[2],current=()=>S.project(pid()),chapter=p=>p?.chapters.find(c=>c.id===S.context.parts[3])||p?.chapters[0];
const head=(label,title,desc='',actions='')=>`<div class="page-heading"><div><span class="eyebrow">${label}</span><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="button-row">${actions}</div></div>`;
const badge=(text)=>`<span class="status-badge ${['失败','待确认','草稿','待同步'].some(v=>text.includes(v))?'amber':''}">${esc(text)}</span>`;
const editorPath=(p,c=p.chapters[0],step='script')=>`/app/editor/${p.id}/${c.id}?step=${step}`;
function projectCard(p){return `<article class="project-card"><a href="#/app/projects/${p.id}" class="project-cover">${art(p.art,p.name)}<span>${p.source==='comic'?'漫画导入':p.mode==='quick'?'快速创作':'工作室项目'}</span></a><div class="project-card-copy"><h3>${link(esc(p.name),'/app/projects/'+p.id)}</h3><p>${esc(p.desc)}</p><div class="row between"><small>${p.chapters.length} 章节 · ${p.updated}</small>${button(p.archived?'恢复':'···',p.archived?'restore-project':'project-menu','mini-button',`data-id="${p.id}" aria-label="管理项目 ${esc(p.name)}"`)}</div></div></article>`;}
function assetCard(a){return link(`${art(a.art,a.name)}<div><span class="eyebrow">${esc(a.type)} / V${a.version}</span><h3>${esc(a.name)}</h3><small>${a.locked?'● 已锁定':'◌ 草稿'} · ${a.resultId?'来自创作工具':'原创示例资产'}</small></div>`,'/app/assets/'+a.id,'asset-card');}
function dashboard(){const p=S.state.projects.filter(v=>!v.archived);return head('YOUR STORY WORKSPACE','欢迎回来，故事还在继续。','今天，想让哪一格先动起来？',link('＋ 新建项目','/app/new','button primary'))+`<div class="stat-grid">${[['项目',p.length,'每个世界，都值得继续。'],['资产',S.state.assets.length,'角色与画风，保持连贯。'],['待确认',S.state.tasks.filter(t=>t.status==='待确认').length,'最后一步，由你决定。'],['模拟模型费用','$4.82','本章预算 $15.00']].map(([t,n,d])=>`<div class="stat-card"><span>${t}</span><strong>${n}</strong><small>${d}</small></div>`).join('')}</div><section class="workspace-section">${S.sectionHead('CONTINUE YOUR STORY','继续创作', '',link('全部项目 →','/app/projects','text-link'))}<div class="project-grid">${p.slice(0,3).map(projectCard).join('')||S.empty('开始你的第一个故事','创意、小说、故事或漫画，都可以成为起点。')}<a class="new-project-card" href="#/app/new"><b>＋</b><h3>下一个故事，从这里开始。</h3><p>选择来源，建立你的创作世界。</p></a></div></section><div class="workspace-columns"><section class="surface padded">${S.sectionHead('IN YOUR LIBRARY','最近资产','',link('资产库 →','/app/assets','text-link'))}<div class="mini-asset-grid">${S.state.assets.slice(0,3).map(assetCard).join('')}</div></section><section class="surface padded">${S.sectionHead('IN PROGRESS','制作动态','',link('任务中心 →','/app/tasks','text-link'))}${S.state.tasks.slice(0,3).map(taskRow).join('')}</section></div>`;}
function projects(){let ps=S.state.projects.filter(p=>!!p.archived===!!S.ui.trash&&(p.name+p.desc).includes(S.ui.projectQuery));return head('YOUR ORIGINAL WORLDS',S.ui.trash?'项目回收站':'我的项目','把灵感变成可持续创作的故事。',button(S.ui.trash?'返回项目':'回收站','toggle-trash','button ghost')+link('＋ 新建项目','/app/new','button primary'))+`<div class="tools-toolbar"><label class="search-box">⌕<input id="project-search" value="${esc(S.ui.projectQuery)}" placeholder="搜索项目…" aria-label="搜索项目"></label><div class="filter-row">${button('▦ 网格','project-view','filter '+(S.ui.projectView==='grid'?'selected':''),'data-value="grid"')}${button('☷ 列表','project-view','filter '+(S.ui.projectView==='list'?'selected':''),'data-value="list"')}</div></div><div id="project-results" class="project-grid ${S.ui.projectView==='list'?'list-view':''}">${ps.map(projectCard).join('')||S.empty('这里还没有项目',S.ui.trash?'归档后的项目可在这里恢复。':'换个关键词，或创建一个新故事。')}</div>`;}
function create(){const source=S.context.params.get('source')||S.state.draft.source,mode=S.context.params.get('mode')||S.state.draft.mode,t=D.templates.find(v=>v.id===S.context.params.get('template')),tool=D.tools.find(v=>v.id===S.context.params.get('tool'));return head('A NEW CHAPTER','从你的故事开始。','先选一个起点，后面的每一步都可以回头调整。')+`<form data-form="create-project" class="create-form"><div class="source-grid">${D.sources.map(v=>`<label class="choice-card"><input type="radio" name="source" value="${v.id}" ${source===v.id?'checked':''}><span>${v.icon}</span><strong>${v.title}</strong><small>${v.desc}</small></label>`).join('')}</div><div class="workspace-columns"><section class="surface padded"><label>项目名称<input name="name" required maxlength="60" placeholder="给你的故事起个名字…" value="${tool?'我的角色故事':t?t.title+' · 新故事':''}"></label><label>第一章标题<input name="chapter" required maxlength="60" value="故事的开始"></label><label>故事内容<textarea name="text" rows="7" placeholder="创意：一句灵感；小说：一个片段；故事：场景、动作与对白；漫画：下步确认切格。">${tool?'从工具结果继续创作，保留角色参考。':''}</textarea></label><label>本机素材（可选）<input type="file" name="file" accept=".txt,image/*" multiple></label><small class="muted">文件仅本机选择；解析和画面使用预置故事示意。</small>${t?`<div class="notice">已带入模板：${esc(t.title)}，可在编辑器调整。</div>`:''}${tool?`<div class="notice">已带入工具结果：${esc(tool.title)}，创建后将加入项目资产。</div>`:''}</section><section class="surface padded"><span class="eyebrow">YOUR WAY OF CREATING</span><h2>选择创作节奏。</h2>${[['quick','快速模式','先看完整初稿，再挑重点修改。'],['studio','工作室模式','逐步确认故事、资产与分镜，费用可控。']].map(([v,h,p])=>`<label class="mode-choice"><input type="radio" name="mode" value="${v}" ${mode===v?'checked':''}><div><strong>${h}</strong><p>${p}</p></div></label>`).join('')}<label>目标输出<select name="output"><option>漫画 + 视频</option><option>漫画长图</option><option>视频短片</option></select></label><div class="notice">✧ 此原型保存你的输入，使用《雨停之前》的原创示例素材展示制作步骤。</div><button class="button primary full">创建项目，继续下一步 ↗</button></section></div></form>`;}
function projectDetail(p){if(!p)return missing();return head('STORY OVERVIEW',p.name,p.desc,button('＋ 新建章节','new-chapter','button ghost',`data-id="${p.id}"`)+link('继续创作 ↗',editorPath(p,p.chapters[0],p.source==='comic'?'assets':'script'),'button primary'))+`<div class="project-summary surface"><div>${art(p.art,p.name)}</div><section><span class="eyebrow">${p.source.toUpperCase()} / ${p.mode==='quick'?'快速模式':'工作室模式'}</span><h2>一个世界，${p.chapters.length} 个章节。</h2><p>${esc(p.text?.slice(0,150)||'用统一的角色和画风，将故事从文字带进画格。')}</p><div class="button-row">${link('绑定资产','/app/assets','button ghost')}${link('推广与分享','/app/promote/'+p.id,'button ghost')}${button('管理项目','project-menu','text-button',`data-id="${p.id}"`)}</div>${p.toolSource?`<p class="notice">来自工具：${esc(D.tools.find(t=>t.id===p.toolSource)?.title||p.toolSource)} · 输入与结果已保留</p>`:''}</section></div><section class="workspace-section">${S.sectionHead('CHAPTERS','你的章节')}<div class="chapter-list">${p.chapters.map((c,i)=>`<article class="chapter-row"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(c.title)}</h3><small>${c.seconds||0} 秒 · ${p.mode==='studio'?'逐步确认':'快速初稿'}</small></div>${badge(c.status)}<div class="button-row">${p.source==='comic'?link('解析确认',`/app/import/${p.id}/${c.id}`,'text-link'):''}${link('同步',`/app/sync/${p.id}/${c.id}`,'text-link')}${link('审查',`/app/review/${p.id}/${c.id}`,'text-link')}${link('编辑 →',editorPath(p,c),'button small')}</div></article>`).join('')}</div></section><section class="workspace-section">${S.sectionHead('STORY ASSETS','项目资产','同一角色，同一画风。',link('管理资产 →','/app/assets','text-link'))}<div class="asset-grid">${S.state.assets.filter(a=>p.assetIds?.includes(a.id)).map(assetCard).join('')||'<p class="muted">暂未绑定资产，可以从资产库添加。</p>'}</div></section>`;}
function assets(id){if(id){const a=S.state.assets.find(a=>a.id===id);if(!a)return missing();const refs=S.state.projects.filter(p=>p.assetIds?.includes(a.id));return S.crumbs([['资产库','/app/assets'],[a.name,null]])+head('ASSET REFERENCE',a.name,`${a.type} / 当前版本 v${a.version}`,button(a.locked?'创建新版本':'锁定此版本',a.locked?'asset-version':'asset-lock','button primary',`data-id="${a.id}"`))+`<div class="asset-detail-grid"><div class="asset-main-image">${art(a.art,a.name)}</div><section class="surface padded"><div class="row between"><h2>身份与约束</h2>${badge(a.locked?'已锁定':'草稿')}</div><p>${esc(a.desc)}</p><div class="detail-list"><div><span>版本记录</span><b>v${a.version}${a.version>1?' ← v'+(a.version-1):' · 初始版本'}</b></div><div><span>使用范围</span><b>${refs.length} 个项目</b></div><div><span>更新影响</span><b>引用镜头需单独同步</b></div></div><h3>引用此资产的项目</h3>${refs.map(p=>link(esc(p.name)+' ↗','/app/projects/'+p.id,'reference-link')).join('')||'<p class="muted">尚未加入项目。</p>'}${button('加入其他项目','asset-attach','button ghost full',`data-id="${a.id}"`)}<p class="muted">新版本只改变本机资产记录，已有画面继续保留；同步页可选择影响范围。</p></section></div><section class="workspace-section">${S.sectionHead('REFERENCE SET','角色与世界参考')}<div class="asset-grid">${[a.art,(a.art+3)%10,(a.art+6)%10].map((v,i)=>`<div class="reference-image">${art(v)}<small>${['主参考','场景参考示意','情绪参考示意'][i]}</small></div>`).join('')}</div></section>`;}
 const types=['全部',...new Set(S.state.assets.map(a=>a.type))];return head('YOUR CONSISTENT WORLD','资产库','角色、场景、服装和声音，都是你故事的一部分。',link('＋ 使用工具创建','/tools/oc-sheet','button primary'))+`<div class="tools-toolbar"><div class="filter-row">${types.map(v=>button(v,'asset-filter','filter '+(S.ui.assetType===v?'selected':''),`data-value="${esc(v)}"`)).join('')}</div><label class="search-box">⌕<input id="asset-search" value="${esc(S.ui.assetQuery)}" placeholder="搜索资产…" aria-label="搜索资产"></label></div><div id="asset-results" class="asset-grid">${filteredAssets()}</div>`;}
function filteredAssets(){return S.state.assets.filter(a=>(S.ui.assetType==='全部'||a.type===S.ui.assetType)&&(a.name+a.desc).includes(S.ui.assetQuery)).map(assetCard).join('')||'<p class="muted">暂无符合条件的资产。</p>';}
function taskRow(t){return link(`<span class="task-symbol">${t.status==='失败'?'!':t.status==='完成'?'✓':'◷'}</span><div><strong>${esc(t.title)}</strong><small>${esc(t.kind)} · 模拟费用 $${t.cost.toFixed(2)}</small></div>${badge(t.status)}`,'/app/tasks/'+t.id,'task-row');}
function tasks(id){if(id){const t=S.state.tasks.find(t=>t.id===id);if(!t)return missing();const p=S.project(t.projectId);return S.crumbs([['任务中心','/app/tasks'],[t.title,null]])+head('TASK INSPECTOR',t.title,'本地状态演示，不提交任何供应商任务。',badge(t.status))+`<div class="workspace-columns"><section class="surface padded"><h2>执行记录</h2><progress max="100" value="${t.progress}"></progress><ol class="task-steps">${t.steps.map((v,i)=>`<li><b>${i+1}</b><div><strong>${esc(v)}</strong><p>${i===1&&t.status==='失败'?'供应商超时示例；未收取真实费用。':'输入、候选与采用版本均保留在本机。'}</p></div></li>`).join('')}</ol><div class="button-row">${t.status==='失败'?button('仅重试失败步骤','retry-task','button primary',`data-id="${t.id}"`):['排队中','生成中','已暂停'].includes(t.status)?button(t.status==='已暂停'?'恢复任务':'暂停任务','pause-task','button primary',`data-id="${t.id}"`):t.status==='待确认'?link('打开人工审查','/app/review/'+p.id+'/'+p.chapters[0].id,'button primary'):badge('结果已保存')}${link('返回项目 →','/app/projects/'+p.id,'button ghost')}</div></section><section class="surface padded">${art(p.art,p.name,'task-preview')}<h3>稳定底稿始终保留</h3><p>增强候选失败时可继续使用稳定版，不重新生成整个章节。</p><div class="detail-list"><div><span>项目</span><b>${esc(p.name)}</b></div><div><span>进度</span><b>${t.progress}%</b></div><div><span>模拟费用</span><b>$${t.cost.toFixed(2)}</b></div></div></section></div>`;}
return head('EVERY STEP, IN SIGHT','任务中心','完成的保留，失败的只重试那一步。',button('创建批处理示例','add-task','button primary'))+`<div class="filter-row">${['全部','排队中','生成中','已暂停','待确认','失败','完成'].map(v=>button(v,'task-filter','filter '+(S.ui.taskFilter===v?'selected':''),`data-value="${v}"`)).join('')}</div><div class="surface padded task-list">${S.state.tasks.filter(t=>S.ui.taskFilter==='全部'||t.status===S.ui.taskFilter).map(taskRow).join('')||'<p class="muted">该状态暂无任务。</p>'}</div>`;}
function exportsPage(){return head('READY FOR THE NEXT CHAPTER','导出与交付','作品、生产报告和推广素材，都在这里。',link('制作推广素材','/app/promote/'+S.project()?.id,'button primary'))+`<div class="notice">HTML漫画是内嵌底图与文字层的独立阅读文件；PNG 为本机示例图片；MP4 仅演示合成流程。历史记录的 JSON 下载是交付说明，不是视频文件。</div><section class="surface padded task-list">${S.state.exports.map(e=>`<div class="export-row"><span class="file-icon">${e.kind}</span><div><h3>${esc(e.name)}</h3><small>${esc(e.size)} · ${esc(e.date)}</small></div>${badge(e.status)}${button(e.comicDelivery?'下载HTML漫画':'下载说明','download-export','button ghost small',`data-id="${e.id}"`)}${link('打开项目','/app/projects/'+e.projectId,'text-link')}</div>`).join('')||S.empty('还没有交付记录','完成章节审批或下载推广素材后显示在这里。')}</section>`;}
function billing(){return head('CREATE WITH CONFIDENCE','套餐与用量','每一次创作，费用都清晰可见。',link('查看所有方案','/pricing','button ghost'))+`<div class="stat-grid"><div class="stat-card"><span>当前模拟方案</span><strong>${esc(S.state.plan)}</strong><small>未订阅、未支付</small></div><div class="stat-card"><span>本章模拟模型费</span><strong>$4.82</strong><small>订阅费与模型费用分别计算</small></div><div class="stat-card"><span>本章预算</span><strong>$${S.state.prefs.budget||15}</strong><small>达到上限则停止新生成</small></div><div class="stat-card"><span>席位</span><strong>1 / ${S.state.plan==='Studio'?5:1}</strong><small>团队能力交互示意</small></div></div><div class="workspace-columns"><section class="surface padded"><h2>模拟费用明细</h2><div class="detail-list">${[['角色与场景参考','1.26'],['漫画分格与局部候选','2.04'],['关键镜头增强','1.52'],['稳定运镜与本机合成','0.00']].map(([n,v])=>`<div><span>${n}</span><b>$${v}</b></div>`).join('')}</div><p class="muted">演示数值，不代表真实模型价格或最终账单。</p>${button('下载费用清单','download-cost','button ghost')}</section><form class="surface padded" data-form="budget"><h2>预算止损</h2><p>生成前显示预计费用；超预算先停止，已有候选和底稿保留。</p><label>每章预算 / USD<input type="number" min="1" max="1000" name="budget" value="${S.state.prefs.budget||15}" required></label><button class="button primary">保存预算偏好</button></form></div>`;}
function settings(){return head('MAKE IT YOURS','工作室设置','偏好和数据只保存在此浏览器。')+`<div class="workspace-columns"><form data-form="settings" class="surface padded"><h2>基本信息</h2><label>工作室名称<input name="studio" required maxlength="40" value="${esc(S.state.prefs.studio)}"></label><label>语言偏好<select name="language"><option>简体中文</option><option ${S.state.prefs.language==='English'?'selected':''}>English</option></select></label><p class="muted">语言选择保存为偏好；本版页面内容保持中文。</p><label class="checkbox-line"><input name="notify" type="checkbox" ${S.state.prefs.notify?'checked':''}> 任务结束时显示站内提示</label><button class="button primary">保存设置</button></form><section class="surface padded"><h2>成员与数据</h2><div class="member-row"><span class="avatar">S</span><div><strong>${esc(S.state.user?.name||'访客创作者')}</strong><small>所有者 · 本地演示</small></div>${badge('1 个席位')}</div>${button('邀请成员示意','invite-member','button ghost')}<hr><h3>带走你的创作记录</h3><p>导出本机的项目、资产、工具参数和工作台状态。素材文件未上传。</p>${button('导出本机数据 JSON','export-data','button ghost full')}<hr>${button('清除全站演示数据…','reset-site','text-button danger')}<p class="muted">清除前可以下载备份；不会删除电脑里的素材。</p></section></div>`;}
function auth(){S.pageTitle='进入创作空间';return `<main class="auth-layout"><div class="auth-story">${S.logo()}${art(6,'林夏与陈序共伞')}<div><span class="eyebrow">YOUR WORLD, EVERY FRAME</span><h1>把喜欢的结果，<br>带进你的故事。</h1><p>同一个角色，从第一格到下一章。</p></div></div><section class="auth-form"><a class="text-link" href="#/">← 返回首页</a><span class="eyebrow">WELCOME TO FRAMEIN</span><h2>故事，从这里继续。</h2><p>这是本地交互原型。进入演示账户即可体验结果保存和项目流转。</p><div class="auth-identity"><span class="avatar">S</span><div><strong>故事创作者</strong><small>creator@example.test</small></div></div>${button('进入演示账户 →','auth','button primary full')}<p class="muted">不需要真实邮箱或密码，不发送身份信息。</p>${link('先以访客体验工作空间','/app','text-link')}<div class="auth-legal">继续体验即表示了解${link('数据说明','/legal/privacy')}与${link('使用条款草案','/legal/terms')}。</div></section></main>`;}
function onboarding(){return `<main class="onboarding wrap">${S.logo()}<span class="eyebrow">LET’S MAKE SOMETHING YOURS</span><h1>你想怎样开始？</h1><p>先看看示例，或直接讲你自己的故事。</p><div class="entry-grid">${D.sources.map(v=>link(`<span class="entry-icon">${v.icon}</span><h3>${v.title}</h3><p>${v.desc}</p>`,'/app/new?source='+v.id,'entry-card')).join('')}</div><div class="button-row">${button('先探索示例工作室 →','finish-onboarding','button primary')}${link('先玩玩小工具','/tools','button ghost')}</div></main>`;}
function importPage(p){if(!p)return missing();const c=chapter(p),order=p.importOrder||[0,1,2,3];return head('COMIC IMPORT / REVIEW','把已有画格，接成新的故事。','选择本机长图，使用示例切格验证边界、阅读顺序和对白归属。',link('返回项目','/app/projects/'+p.id,'button ghost'))+`<div class="import-top surface padded"><label class="upload-area compact-upload"><input id="comic-import-file" type="file" accept="image/*"><span>${importURL?`<img src="${importURL}" alt="本机漫画预览">`:'<b>↥</b><strong>选择漫画长图</strong><small>本机预览，不上传</small>'}</span></label><div><h2>识别 4 格 · 1 处需你确认</h2><p>下方使用原创示例，不是真实自动解析结果。可改变顺序，编辑 OCR 和角色归属。</p><label>阅读方向<select id="reading-direction"><option>从上到下</option><option>从右到左</option><option>从左到右</option></select></label>${button('加载示例长图','sample-import','text-link')}</div></div><div class="import-panels">${order.map((v,i)=>`<section class="surface padded"><div class="row between"><h3>分格 ${i+1}</h3>${badge(i===2?'归属待确认':'已识别')}</div><div class="boundary-preview">${art(v)}<span>可调整裁切范围</span></div><label>裁切边界（底部 / %）<input data-import-bound="${i}" type="range" min="55" max="100" value="${p.importBounds?.[i]||100}" aria-label="分格 ${i+1} 裁切边界"></label><label>OCR 对白<input data-import-text="${i}" value="${esc(p.importTexts?.[i]||['那家书店还在。','七年了，你还记得我吗？','我以为，你不会再来了。','这封信，终于交给你。'][v])}"></label><label>对白归属<select data-import-speaker="${i}">${['旁白','林夏','陈序'].map(n=>`<option ${(p.importSpeakers?.[i]||['旁白','林夏','陈序','林夏'][v])===n?'selected':''}>${n}</option>`).join('')}</select></label><div class="button-row">${button('↑ 上移','import-up','button ghost small',`data-index="${i}" ${i===0?'disabled':''}`)}${button('↓ 下移','import-down','button ghost small',`data-index="${i}" ${i===3?'disabled':''}`)}</div></section>`).join('')}</div><div class="sticky-actions surface"><span>确认阅读顺序、裁切与对白后，进入资产绑定。</span>${button('确认解析，进入资产 →','confirm-import','button primary',`data-project="${p.id}" data-chapter="${c.id}"`)}</div>`;}
function syncPage(p){if(!p)return missing();const c=chapter(p);return head('VERSION DIFF & SYNC','只更新变化的那一格。','新分格与旧镜头并存，先决定影响范围，再继续制作。',link('返回画布',editorPath(p,c,'motion'),'button ghost'))+`<div class="sync-comparison"><section class="surface padded"><span class="eyebrow">CURRENT / 当前采用 v1</span>${art(1,'旧分格')}<p>稳定底稿 · 角色资产 v1 · 4 秒</p></section><section class="surface padded"><span class="eyebrow">NEW / 新分格 v2</span>${art(8,'新分格参考示意')}<p>表情参考变化 · 仅示例画面差异</p></section></div><form data-form="sync" class="surface padded"><h2>选择需要更新的内容</h2><label class="checkbox-line"><input type="checkbox" name="frame" checked> 镜头 02 / 背景与角色底稿（稳定运镜重合成 $0）</label><label class="checkbox-line"><input type="checkbox" name="subtitle" checked> 关联对白和字幕（本机参数示意）</label><label class="checkbox-line"><input type="checkbox" name="enhanced"> 重新生成增强候选（模拟预计 $0.18）</label><div class="notice">其余 9 个镜头保持当前采用版本。新增强候选需人工采用；预算不足将停止。</div><div class="button-row"><button class="button primary">确认所选同步范围</button>${button('保留当前版本','keep-version','button ghost',`data-project="${p.id}" data-chapter="${c.id}"`)}</div></form>`;}
function reviewPage(p){if(!p)return missing();const c=chapter(p);return head('A HUMAN FINAL SAY','最后一眼，由你决定。','逐项检查字幕、表情和版权，批注保存在当前章节。',link('回到镜头',editorPath(p,c,'motion'),'button ghost'))+`<div class="workspace-columns"><section class="surface padded"><h2>章节审查 · ${esc(c.title)}</h2>${[['subtitle','镜头 04 / 字幕安全区','字幕靠近下方平台控件，建议上移 24 px。'],['character','镜头 09 / 表情一致性','笑容比角色参考更明显，确认是否符合剧情。'],['rights','素材与声音使用权','确认拥有本章素材与音色的合法使用权。']].map(([v,t,d])=>`<label class="review-check"><input type="checkbox" data-review="${v}" ${reviewChecks.has(p.id+c.id+v)?'checked':''}><div><strong>${t}</strong><p>${d}</p></div></label>`).join('')}<form data-form="comment"><label>章节批注<textarea name="comment" required placeholder="记录需要调整的情绪、对白或镜头…"></textarea></label><button class="button ghost">保存批注</button></form><div class="comment-list">${(c.comments||[]).map(x=>`<p><b>创作者</b> ${esc(x)}</p>`).join('')}</div></section><section class="surface padded">${art(8,'表情参考','task-preview')}<h2>确认后进入导出</h2><p>这里只保存审查清单；编辑器仍会检查对应镜头与最终审批。</p>${button('审查完成，打开导出 →','finish-review','button primary full',`data-project="${p.id}" data-chapter="${c.id}"`)}</section></div>`;}
function promotePage(p){if(!p)return missing();if(promote.project!==p.id){promote={...promote,project:p.id,title:p.name,author:S.state.prefs.studio};}return head('LET YOUR STORY TRAVEL','让更多人，遇见你的故事。','从作品里提取传播素材，预览不同尺寸，再带走你满意的那一张。',link('交付记录','/app/exports','button ghost'))+`<div class="promote-layout"><section class="surface padded"><span class="eyebrow">01 / MATERIAL</span><h2>这次，分享哪一面？</h2><label>素材类型<select id="promote-type">${['作品封面','角色设定卡','表情参考图','前后对比图','制作过程','15 秒预告'].map(v=>`<option ${promote.type===v?'selected':''}>${v}</option>`).join('')}</select></label><label>渠道尺寸<select id="promote-ratio">${['9:16','1:1','16:9','3:4'].map(v=>`<option ${promote.ratio===v?'selected':''}>${v}</option>`).join('')}</select></label><label>作品标题<input id="promote-title" maxlength="35" value="${esc(promote.title)}"></label><label>一句话介绍<textarea id="promote-subtitle" maxlength="100">${esc(promote.subtitle)}</textarea></label><label>作者署名<input id="promote-author" maxlength="30" value="${esc(promote.author)}"></label><label class="checkbox-line"><input type="checkbox" id="promote-safe" checked> 显示渠道安全区</label><p class="muted">PNG 可真实下载；预告仅 CSS 动画与字幕示意，不生成真实视频。</p>${button('下载示例 PNG','download-promo','button primary full',`data-project="${p.id}"`)}${button('预览与分享 →','share-dialog','button ghost full',`data-project="${p.id}"`)}</section><section class="surface promo-preview-section"><div class="panel-heading"><span>02 / CHANNEL PREVIEW</span><span id="promo-spec">${promote.ratio}</span></div><div id="promo-preview-body">${promoPreview(p)}</div><small class="muted">安全区仅作布局参考。不会连接社交账号或向平台发布。</small></section></div><section class="workspace-section surface padded"><h2>本机分享记录</h2>${S.state.shares.filter(s=>s.projectId===p.id).map(s=>`<div class="export-row"><div><strong>${esc(s.title)}</strong><small>${s.revoked?'已撤销':'仅此浏览器可预览'} · ${s.audience}</small></div>${s.revoked?'':link('打开只读页 ↗','/share/'+s.id,'text-link')}${button(s.revoked?'恢复预览':'撤销预览','revoke-share','text-button',`data-id="${s.id}"`)}</div>`).join('')||'<p class="muted">还没有分享预览，完成设置后会保存在这里。</p>'}</section>`;}
function promoPreview(p){const type=promote.type;return `<div class="promo-canvas ${type==='15 秒预告'?'promo-playing':''}" id="promo-canvas" style="aspect-ratio:${promote.ratio.replace(':','/')};max-width:${promote.ratio==='16:9'?'680':'400'}px"><div class="promo-pictures ${['前后对比图','制作过程'].includes(type)?'split':type==='表情参考图'?'six':''}">${(type==='角色设定卡'?[1]:type==='表情参考图'?[1,8,3,6,4,9]:type==='前后对比图'?[1,8]:type==='制作过程'?[0,1,2]:[p.art]).map(v=>art(v)).join('')}</div><div class="promo-shade"></div><div class="safe-zone" id="safe-zone"></div><div class="promo-copy"><span id="promo-material">${esc(type)} / FRAMEIN</span><h2 id="promo-live-title">${esc(promote.title)}</h2><p id="promo-live-subtitle">${esc(promote.subtitle)}</p><small id="promo-live-author">BY ${esc(promote.author)}</small></div></div>`;}
function sharePage(id){const s=S.state.shares.find(s=>s.id===id);S.pageTitle='作品分享预览';if(!s||s.revoked)return `<main class="wrap share-page">${S.logo()}${S.empty('此预览暂不可用','分享仅保存在创建它的浏览器；链接不代表作品已经发布。','返回创作空间','/app')}</main>`;const p=S.project(s.projectId);return `<header class="share-header">${S.logo()}<span class="demo-pill">${s.audience} · 本机只读预览</span>${link('回到创作空间','/app','button ghost small')}</header><main class="share-page wrap"><span class="eyebrow">AN ORIGINAL STORY / MADE WITH FRAMEIN</span><h1>${esc(s.title)}</h1><p>${esc(s.subtitle)}</p><small>作者 / ${esc(s.author)}</small><div class="filter-row centered">${button('漫画阅读','share-mode','filter selected','data-value="comic"')}${button('视频示意','share-mode','filter','data-value="motion"')}</div><section id="share-view" class="share-comic">${[0,1,2,3,6].map((v,i)=>`<figure>${art(v)}<figcaption>${['那家书店，还在原来的地方。','七年了，你还记得我吗？','我以为，你不会再来了。','有些话，写了很久也没寄出去。','这一次，一起走吧。'][i]}</figcaption></figure>`).join('')}</section><div class="share-credit"><p>原创示例插画 · 可编辑分格 · 稳定运镜</p>${button('使用同款示例继续创作 ↗','copy-case','button primary','data-id="rain"')}${link('体验免费创作工具','/tools','button ghost')}<p class="muted">这是本机原型预览，没有向互联网发布作品。</p>${link('返回推广素材','/app/promote/'+p.id,'text-link')}</div></main>`;}
function editor(ctx){const p=S.project(ctx.parts[2]),c=p?.chapters.find(c=>c.id===ctx.parts[3]);if(!p||!c)return missing();S.pageTitle=p.name+' · '+c.title;const step=['script','assets','comic','motion','export'].includes(ctx.params.get('step'))?ctx.params.get('step'):'script';return `<div class="editor-frame-shell"><header class="editor-frame-header">${link('← 项目','/app/projects/'+p.id,'button ghost small')}<div><strong>${esc(p.name)}</strong><small>${esc(c.title)} · 原创示例素材</small></div><nav>${p.source==='comic'?link('漫画解析',`/app/import/${p.id}/${c.id}`):''}${link('差异同步',`/app/sync/${p.id}/${c.id}`)}${link('质量审查',`/app/review/${p.id}/${c.id}`)}${link('任务','/app/tasks')}${link('推广与分享','/app/promote/'+p.id)}</nav></header><iframe id="studio-frame" title="${esc(p.name)}章节创作工作台" src="studio.html?project=${encodeURIComponent(p.id)}&chapter=${encodeURIComponent(c.id)}&embed=1#${step}"></iframe></div>`;}
function missing(){return S.empty('没有找到这份内容','内容可能已归档，返回工作空间继续查看。','返回工作空间','/app');}
function render(ctx){const k=ctx.parts[1],id=ctx.parts[2];S.pageTitle=title(ctx);if(ctx.path==='/auth')return auth();if(ctx.path==='/onboarding')return onboarding();if(ctx.parts[0]==='share')return sharePage(ctx.parts[1]);if(ctx.path==='/app')return dashboard();switch(k){case'projects':return id?projectDetail(S.state.projects.find(p=>p.id===id)):projects();case'new':return create();case'assets':return assets(id);case'tasks':return tasks(id);case'exports':return exportsPage();case'billing':return billing();case'settings':return settings();case'import':return importPage(current());case'sync':return syncPage(current());case'review':return reviewPage(current());case'promote':return promotePage(current());default:return missing();}}
function title(ctx){return ({projects:'我的项目',new:'新建项目',assets:'资产库',tasks:'任务中心',exports:'导出与交付',billing:'个人中心',settings:'个人中心',import:'漫画导入',sync:'差异同步',review:'质量审查',promote:'推广与分享'})[ctx.parts[1]]||'工作空间';}
function createProject(values){const p={id:S.id('project'),name:values.name.trim(),desc:values.output||'从一个新故事开始',text:values.text||'',source:values.source||'script',mode:values.mode||'studio',art:6,updated:'刚刚',assetIds:[],chapters:[{id:'ch1',title:values.chapter||'故事的开始',status:values.source==='comic'?'解析待确认':'故事草稿',seconds:48}]};S.state.projects.unshift(p);S.state.draft={source:p.source,mode:p.mode};S.save();return p;}
function projectMenu(id){const p=S.project(id);S.modal('管理「'+p.name+'」',`<p>复制会创建独立项目；归档后可在回收站恢复。</p>`,button('复制项目','duplicate-project','button ghost',`data-id="${p.id}"`)+button('移至回收站','archive-project','button ghost danger',`data-id="${p.id}"`));}
function shareDialog(p){S.modal('先预览，再让故事出发。',`<form data-form="share" data-project="${p.id}"><label>展示内容<select name="content"><option>漫画与视频示意</option><option>漫画长图</option><option>作品封面</option></select></label><label>可见性<select name="audience"><option>持链接可见（示意）</option><option>私密预览（示意）</option></select></label><p class="notice">只生成本机预览链接，其他设备无法读取。作品不会发布到互联网，访问控制也未实现。</p><button class="button primary full">创建只读预览 →</button></form>`);}
async function downloadPromo(p){if(promote.type==='15 秒预告'){S.download({prototype:true,project:p.name,type:promote.type,duration:15,ratio:promote.ratio,title:promote.title,notice:'预告脚本示意，无真实 MP4'},p.name+'-预告脚本.json');return;}const [x,y]=promote.ratio.split(':').map(Number),canvas=document.createElement('canvas');canvas.width=1080;canvas.height=Math.round(1080*y/x);const ctx=canvas.getContext('2d'),indices=promote.type==='表情参考图'?[1,8,3,6,4,9]:['前后对比图','制作过程'].includes(promote.type)?[1,8]:[promote.type==='角色设定卡'?1:p.art];try{const imgs=await Promise.all(indices.map(async i=>{const img=new Image();img.src=Art.url(i);await img.decode();return img;}));imgs.forEach((img,i)=>{const cols=indices.length===6?2:indices.length,rows=indices.length===6?3:1,w=canvas.width/cols,h=canvas.height/rows,dx=i%cols*w,dy=Math.floor(i/cols)*h,scale=Math.max(w/img.width,h/img.height);ctx.save();ctx.beginPath();ctx.rect(dx,dy,w,h);ctx.clip();ctx.drawImage(img,dx+(w-img.width*scale)/2,dy+(h-img.height*scale)/2,img.width*scale,img.height*scale);ctx.restore();});const grad=ctx.createLinearGradient(0,canvas.height*.35,0,canvas.height);grad.addColorStop(0,'#15151b00');grad.addColorStop(1,'#15151bf5');ctx.fillStyle=grad;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#f7f1e8';ctx.font='bold 72px sans-serif';ctx.fillText(promote.title,70,canvas.height-200,940);ctx.font='30px sans-serif';ctx.fillText(promote.subtitle,70,canvas.height-135,940);ctx.font='24px sans-serif';ctx.fillText('BY '+promote.author+' / FRAMEIN · 示例',70,canvas.height-65,940);canvas.toBlob(b=>{if(!b){S.toast('图片合成失败，请重试。');return;}S.download(b,p.name+'-'+promote.type+'.png','image/png');S.state.exports.unshift({id:S.id('export'),projectId:p.id,name:p.name+' · '+promote.type,kind:'PNG',status:'完成',size:canvas.width+' × '+canvas.height,date:'刚刚'});S.save();});}catch{S.toast('图片未加载完成，请重试。');}}
function onClick(a,el){const id=el.dataset.id,p=S.project(el.dataset.project||pid());switch(a){case'finish-onboarding':S.state.onboarded=true;S.save();S.route('/app');break;case'toggle-trash':S.ui.trash=!S.ui.trash;S.render();break;case'project-view':S.ui.projectView=el.dataset.value;S.render();break;case'project-menu':projectMenu(id);break;case'duplicate-project':{const old=S.project(id),copy=JSON.parse(JSON.stringify(old));copy.id=S.id('project');copy.name+=' · 副本';copy.updated='刚刚';copy.archived=false;S.state.projects.unshift(copy);S.save();S.route('/app/projects/'+copy.id);break;}case'archive-project':S.project(id).archived=true;S.save();S.route('/app/projects');S.toast('项目已归档，可在回收站恢复。');break;case'restore-project':S.project(id).archived=false;S.save();S.render();break;case'new-chapter':S.modal('开启下一章',`<form data-form="new-chapter" data-project="${id}"><label>章节标题<input name="title" required maxlength="60" placeholder="下一格，会发生什么？"></label><button class="button primary full">创建章节</button></form>`);break;case'copy-case':{const c=D.cases.find(v=>v.id===id)||D.cases[0],p=createProject({name:c.title+' · 我的版本',chapter:'重逢的第七天',source:'script',mode:'studio'});p.art=c.art;p.assetIds=['linxia','chenxu','shop'];p.copiedExample=true;S.save();S.route('/app/projects/'+p.id);S.toast('已建立独立示例项目。');break;}case'asset-filter':S.ui.assetType=el.dataset.value;S.render();break;case'asset-version':{const asset=S.state.assets.find(v=>v.id===id);S.modal('创建资产新版本',`<form data-form="asset-version" data-id="${id}"><p>已有版本与引用画面保留；新版本在同步前不影响已采用结果。</p><label>新版本约束<textarea required name="desc">${esc(asset.desc)}</textarea></label><button class="button primary full">创建 v${asset.version+1} 草稿</button></form>`);break;}case'asset-lock':{const asset=S.state.assets.find(v=>v.id===id);asset.locked=true;S.save();S.render();S.toast('已锁定当前资产版本。');break;}case'asset-attach':S.modal('选择引用项目',`<div class="project-pick-list">${S.state.projects.filter(v=>!v.archived).map(p=>button(esc(p.name)+' →','attach-asset','project-pick',`data-id="${id}" data-project="${p.id}"`)).join('')}</div>`);break;case'attach-asset':p.assetIds??=[];if(!p.assetIds.includes(id))p.assetIds.push(id);S.save();S.route('/app/projects/'+p.id);break;case'task-filter':S.ui.taskFilter=el.dataset.value;S.render();break;case'add-task':{const t={id:S.id('task'),title:'资产批量规范化示例',projectId:S.project().id,status:'排队中',progress:0,cost:0,kind:'批处理',steps:['检查命名与尺寸','生成规范建议','保留原素材']};S.state.tasks.unshift(t);S.save();S.route('/app/tasks/'+t.id);break;}case'pause-task':{const t=S.state.tasks.find(v=>v.id===id);t.status=t.status==='已暂停'?'生成中':'已暂停';S.save();S.render();if(t.status==='生成中')completeTask(t);break;}case'retry-task':{const t=S.state.tasks.find(v=>v.id===id);t.status='生成中';t.progress=65;S.save();S.render();completeTask(t);break;}case'download-export':{const e=S.state.exports.find(e=>e.id===id);S.download({...e,prototype:true,notice:'交付记录说明，不是真实视频或素材文件'},'framein-delivery-'+id+'.json');break;}case'confirm-plan':S.state.plan=el.dataset.plan||'Free';S.state.cycle=S.ui.cycle||S.state.cycle;S.save();S.close();S.route('/app/billing');S.toast('方案已模拟切换，没有扣款或订阅。');break;case'download-cost':S.download({prototype:true,currency:'USD',total:4.82,budget:S.state.prefs.budget||15,notice:'模拟成本，不是真实账单'},'framein-demo-cost.json');break;case'invite-member':S.modal('成员邀请示意',`<p>工作室版可为不同成员分配编辑、审查和只读职责。此原型不发送邮件，不创建真实邀请。</p><label>成员角色<select><option>编辑者</option><option>审查者</option><option>只读访客</option></select></label>`,button('了解，返回工作室','close','button primary'));break;case'export-data':{const editors={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k.startsWith('framein-m0-')){try{editors[k]=JSON.parse(localStorage.getItem(k));}catch{}}}S.download({site:S.state,editors,prototype:true},'framein-local-backup.json');break;}case'reset-site':S.modal('清除全站演示数据？','<p>将清除本浏览器的全站项目、分享及工作台记录，恢复初始示例。建议先下载数据备份。</p>',button('先下载备份','export-data','button ghost')+button('确认清除并恢复示例','confirm-reset-site','button danger'));break;case'confirm-reset-site':{const keys=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k==='framein-site-v1'||k.startsWith('framein-m0-'))keys.push(k);}keys.forEach(k=>localStorage.removeItem(k));location.hash='/';location.reload();break;}case'sample-import':if(importURL)URL.revokeObjectURL(importURL);importURL=Art.url(0);S.render();S.toast('已加载示例，真实切格未执行。');break;case'import-up':case'import-down':{p.importOrder??=[0,1,2,3];const i=+el.dataset.index,j=i+(a==='import-up'?-1:1);if(j>=0&&j<4){[p.importOrder[i],p.importOrder[j]]=[p.importOrder[j],p.importOrder[i]];for(const k of ['importTexts','importSpeakers','importBounds'])if(p[k])[p[k][i],p[k][j]]=[p[k][j],p[k][i]];S.save();S.render();}break;}case'confirm-import':p.importConfirmed=true;chapter(p).status='资产待确认';S.save();S.route(editorPath(p,chapter(p),'assets'));break;case'keep-version':S.toast('已保留旧底稿，本次未重做。');S.route(editorPath(p,chapter(p),'motion'));break;case'finish-review':{const c=chapter(p);if(['subtitle','character','rights'].some(v=>!reviewChecks.has(p.id+c.id+v))){S.toast('请先逐项确认审查清单。');return true;}c.status='审查完成';S.save();S.route(editorPath(p,c,'export'));break;}case'download-promo':downloadPromo(p);break;case'share-dialog':shareDialog(p);break;case'copy-share':{const url=location.origin+location.pathname+'#/share/'+id;navigator.clipboard?.writeText(url).then(()=>S.toast('本机预览链接已复制，其他设备无法读取此数据。'),()=>S.modal('复制本机预览链接',`<input readonly value="${esc(url)}">`));break;}case'revoke-share':{const s=S.state.shares.find(v=>v.id===id);s.revoked=!s.revoked;S.save();S.render();break;}case'share-mode':{S.$$('.share-page .filter').forEach(b=>b.classList.toggle('selected',b===el));const v=S.$('#share-view');v.className=el.dataset.value==='comic'?'share-comic':'share-motion';v.querySelectorAll('figure').forEach((f,i)=>f.hidden=el.dataset.value==='motion'&&i!==1);break;}default:return false;}return true;}
function completeTask(t){setTimeout(()=>{if(t.status==='生成中'){t.status='完成';t.progress=100;t.steps=['原始输入已保留','失败步骤模拟重试完成','采用结果待你检查'];S.save();if(S.context.path.startsWith('/app/tasks'))S.render();S.toast('示例任务已完成，没有真实模型调用。');}},1200);}
function onSubmit(f){const v=Object.fromEntries(new FormData(f)),p=current();switch(f.dataset.form){case'create-project':{const created=createProject(v),tool=S.context.params.get('tool');if(tool&&S.state.results[tool]?.status==='ready'){S.tools.attach(tool,created.id);}else S.route(v.source==='comic'?`/app/import/${created.id}/ch1`:editorPath(created));S.toast('项目已创建，你的输入保存在本机。');break;}case'new-chapter':{const target=S.project(f.dataset.project);target.chapters.push({id:S.id('ch'),title:v.title,status:'故事草稿',seconds:48});S.save();S.route('/app/projects/'+target.id);break;}case'asset-version':{const asset=S.state.assets.find(a=>a.id===f.dataset.id);asset.history??=[];asset.history.push({version:asset.version,desc:asset.desc});asset.version++;asset.desc=v.desc;asset.locked=false;S.save();S.close();S.render();break;}case'budget':S.state.prefs.budget=Number(v.budget);S.save();S.toast('预算偏好已保存，下次打开章节时应用。');break;case'settings':Object.assign(S.state.prefs,{studio:v.studio,language:v.language,notify:!!v.notify});S.save();S.render();S.toast('工作室设置已保存。');break;case'sync':{const fields=['frame','subtitle','enhanced'].filter(k=>v[k]);if(!fields.length){S.toast('至少选择一项，或保留当前版本。');break;}if(v.enhanced&&(S.state.prefs.budget||15)<5){S.toast('模拟预算不足，增强重做已停止；可取消增强选项。');break;}p.sync={fields,cost:v.enhanced?.18:0,date:Date.now()};S.state.tasks.unshift({id:S.id('sync'),title:'所选镜头版本同步',projectId:p.id,status:'完成',progress:100,cost:v.enhanced?.18:0,kind:'差异同步',steps:['锁定所选影响范围','重合成稳定运镜示意','保留原增强候选，等待新采用']});S.save();S.route(editorPath(p,chapter(p),'motion'));S.toast('同步范围已记录，其他镜头保留。');break;}case'comment':chapter(p).comments??=[];chapter(p).comments.push(v.comment);S.save();S.render();S.toast('批注已保存在本章。');break;case'share':{const share={id:S.id('share'),projectId:f.dataset.project,title:promote.title,subtitle:promote.subtitle,author:promote.author,audience:v.audience,content:v.content};S.state.shares.unshift(share);S.save();S.modal('只读预览已准备好。',`<p>仅此浏览器可访问数据，未发布到互联网。</p><input readonly value="${esc(location.origin+location.pathname+'#/share/'+share.id)}">`,button('复制本机链接','copy-share','button ghost',`data-id="${share.id}"`)+link('打开只读预览 ↗','/share/'+share.id,'button primary'));break;}default:return false;}return true;}
function refreshPromo(){const p=current();S.$('#promo-preview-body').innerHTML=promoPreview(p);S.$('#promo-spec').textContent=promote.ratio;if(S.$('#safe-zone'))S.$('#safe-zone').hidden=!S.$('#promote-safe').checked;}
function onInput(el){if(el.id==='project-search'){S.ui.projectQuery=el.value;S.$('#project-results').innerHTML=S.state.projects.filter(p=>!!p.archived===!!S.ui.trash&&(p.name+p.desc).includes(el.value)).map(projectCard).join('')||'<p class="muted">没有匹配的项目。</p>';}if(el.id==='asset-search'){S.ui.assetQuery=el.value;S.$('#asset-results').innerHTML=filteredAssets();}if(el.id.startsWith('promote-')&&['title','subtitle','author'].includes(el.id.slice(8))){const key=el.id.slice(8);promote[key]=el.value;const n=S.$('#promo-live-'+key);if(n)n.textContent=(key==='author'?'BY ':'')+el.value;}if(el.dataset.importText!==undefined){const p=current();p.importTexts??={};p.importTexts[el.dataset.importText]=el.value;S.save();}if(el.dataset.importBound!==undefined){const p=current();p.importBounds??={};p.importBounds[el.dataset.importBound]=+el.value;el.closest('section').querySelector('.boundary-preview img').style.clipPath=`inset(0 0 ${100-el.value}% 0)`;S.save();}}
function onChange(el){if(['promote-type','promote-ratio'].includes(el.id)){promote[el.id.slice(8)]=el.value;refreshPromo();}if(el.id==='promote-safe')S.$('#safe-zone').hidden=!el.checked;if(el.dataset.importSpeaker!==undefined){const p=current();p.importSpeakers??={};p.importSpeakers[el.dataset.importSpeaker]=el.value;S.save();}if(el.dataset.review){const key=current().id+chapter(current()).id+el.dataset.review;el.checked?reviewChecks.add(key):reviewChecks.delete(key);}if(el.id==='comic-import-file'){const f=el.files[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>20e6){S.toast('请选择 20 MB 以内的图片。');return;}if(importURL)URL.revokeObjectURL(importURL);importURL=URL.createObjectURL(f);S.render();S.toast('已读取本机预览；下方切格仍为示例。');}}
S.workspace={title,render,editor,onClick,onSubmit,onInput,onChange,afterRender(){}};
})();

